package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenPercentageMeaningScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1",ID=PercentageMeaning.ID;
 private static Question question(String p){return new Question(ID,PercentageMeaning.prompt(p),"-999.123456789","999","999%");}
 @Test public void normalNaSevenDefinitionAndSymbolStayTwoTypedAnswersWithAllHundredOneFreshParts(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(pack.inGrade(ID,7));assertFalse(pack.inGrade(ID,6));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals(ID)).count());assertEquals("백분율의 뜻과 기호",Catalog.get(ID).title);CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,ID,7);
  for(boolean multipleChoice:List.of(false,true)){Generator gen=new Generator(new Random(361));List<String> recent=new ArrayList<>();Set<Integer> parts=new HashSet<>();
   for(int i=0;i<101;i++){Question q=gen.next(ID,recent,multipleChoice,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=PercentageMeaning.read(q);assertNotNull(g);int p=g.percent().intValue();parts.add(p);assertTrue(p>=0&&p<=100);assertTrue(limits.allows(q));assertEquals(ID,q.kind);assertEquals(ID,q.answerFormat);assertArrayEquals(new String[]{"기준 부분 수","백분율"},q.labels);assertArrayEquals(new String[]{"100",p+"%"},q.answers);assertTrue(q.choices.isEmpty());assertTrue(q.choiceLabels.isEmpty());assertEquals(-1,q.correctChoice);assertFalse(FractionInput.available(q));assertFalse(q.stepSupport);assertEquals(4,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(new Checker().check(q,List.of(),Arrays.asList(q.answers)).correct());}
   assertEquals(101,parts.size());assertTrue(parts.contains(0)&&parts.contains(100));assertEquals(recent.get(0),gen.next(ID,recent,multipleChoice,limits).signature());
  }
  Question created=new Generator(new Random(361)).create(Catalog.get(ID));assertNotNull(PercentageMeaning.read(created));assertEquals(ID,created.kind);assertEquals(2,created.answers.length);
 }
 @Test public void declaredSupplyFiltersUseOnlyPublicPartsAndResultsWithoutBoundingGeneralPercentages(){
  Question q=question("35");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;CurriculumLimits selected=GlobalCurriculum.limits(SYSTEM,ID,7);assertTrue(selected.allows(q));q.expression=null;q.answers=null;assertTrue(selected.allows(q));assertTrue(new CurriculumLimits("maxGiven=35;minGiven=0;nonnegative=true").allows(q));assertFalse(new CurriculumLimits("maxGiven=34").allows(q));assertFalse(new CurriculumLimits("minGiven=36").allows(q));assertTrue(new CurriculumLimits("maxResult=100").allows(q));assertFalse(new CurriculumLimits("maxResult=99").allows(q));assertFalse(new CurriculumLimits("percentages=25,50").allows(q));assertTrue(new CurriculumLimits("percentages=35").allows(q));assertTrue(new CurriculumLimits("denominators=100").allows(q));assertFalse(new CurriculumLimits("denominators=10").allows(q));assertEquals(4,HelpPlan.forQuestion(q).size());assertSame(stored,q.studyGuide);assertNull(q.expression);assertNull(q.answers);
  Question decimal=question("150.50");assertNotNull(PercentageMeaning.read(decimal));assertFalse(selected.allows(decimal));assertTrue(CurriculumLimits.NONE.allows(decimal));assertTrue(new CurriculumLimits("minGiven=100;maxGiven=200;maxResult=200;answerDomain=rational;answerDecimalPlaces=1").allows(decimal));assertFalse(new CurriculumLimits("answerDomain=integer").allows(decimal));assertTrue(new CurriculumLimits("answerDecimalPlaces=1").allows(decimal));assertFalse(new CurriculumLimits("answerDecimalPlaces=0").allows(decimal));assertFalse(new CurriculumLimits("decimalPlaces=1").allows(decimal));assertFalse(new CurriculumLimits("maxFractionValue=1").allows(decimal));assertFalse(new CurriculumLimits("wholeMaximum=100").allows(decimal));assertTrue(new Checker().check(decimal,List.of(),List.of("100","150.5%")).correct());
  Question tiny=question("0.50");assertFalse(selected.allows(tiny));assertTrue(CurriculumLimits.NONE.allows(tiny));assertFalse(new CurriculumLimits("maxGiven=0.0000000000001").allows(question("0.000000000001")));assertTrue(new CurriculumLimits("maxGiven=1e300").allows(q));Question huge=question("99999999999999999999.123456789012");huge.expression=null;huge.answers=null;assertTrue(CurriculumLimits.NONE.allows(huge));assertFalse(selected.allows(huge));
 }
 @Test public void legacyPercentConversionsAndEarlierNamibiaFractionTopicsKeepTheirOwnContracts(){
  Question oldFraction=PercentageNotation.make(PercentageNotation.FRACTION,35),oldDecimal=PercentageNotation.make(PercentageNotation.DECIMAL,35);assertTrue(new Checker().check(oldFraction,List.of(),List.of("35/100")).correct());assertFalse(new Checker().check(oldFraction,List.of(),List.of("7/20")).correct());assertEquals(3,HelpPlan.forQuestion(oldFraction).size());assertEquals(4,HelpPlan.forQuestion(oldDecimal).size());assertTrue(new Checker().check(oldDecimal,List.of(),List.of("0.35")).correct());assertEquals("percentage-notation-v1",HelpPlan.forQuestion(oldFraction).restore(null,oldFraction.id).teachingVersion);assertFalse(HelpPlan.forQuestion(oldFraction).canTransfer());assertFalse(HelpPlan.forQuestion(oldDecimal).canTransfer());
  Question reverse=DecimalPercentReverse.make(350);assertTrue(new Checker().check(reverse,List.of(),List.of("35")).correct());assertFalse(new Checker().check(reverse,List.of(),List.of("35%")).correct());assertEquals(4,HelpPlan.forQuestion(reverse).size());assertEquals("decimal-percent-reverse-v1",HelpPlan.forQuestion(reverse).restore(null,reverse.id).teachingVersion);assertEquals(2,FractionPercentEquivalence.make(1,2).answers.length);
  var na=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(na.inGrade("percent",7));assertFalse(na.inGrade(PercentageNotation.FRACTION,7));assertFalse(na.inGrade(PercentageNotation.DECIMAL,7));assertEquals(2,GlobalCurriculum.limits(SYSTEM,DecimalToFractionSupply.ID,6).decimalPlaces(1));
  Question third=new Question(FractionDecimalRecall.ID,FractionDecimalRecall.prompt("1","3"),"poison","999");assertTrue(new Checker().check(third,List.of(),List.of("0.(3)")).correct());assertFalse(new Checker().check(third,List.of(),List.of("0.333")).correct());assertEquals(4,HelpPlan.forQuestion(third).size());Question rounded=new Question(FractionToDecimalCheck.ID,FractionDecimalDivision.prompt("1","3"),"poison","999");assertTrue(new Checker().check(rounded,List.of(),List.of("0.333")).correct());assertEquals(23,HelpPlan.forQuestion(rounded).size());Question reduced=DecimalToFractionSupply.makeReduced(0,45,2);assertTrue(new Checker().check(reduced,List.of(),List.of("9/20")).correct());assertEquals(7,HelpPlan.forQuestion(reduced).size());
 }
}
